head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf60001";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf60001.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb2", fn: function () { return String((dma_pageContext.get("lastyear2") ?? "")) + "년"; } },
        { childId: "__rb3", fn: function () { return String((dma_pageContext.get("lastyear1") ?? "")) + "년"; } },
        { childId: "__rb4", fn: function () { return String((dma_pageContext.get("curryear") ?? "")) + "년"; } },
        { childId: "__rb7", fn: function () { return String((dma_pageContext.get("lastyear2") ?? "")) + "년"; } },
        { childId: "__rb8", fn: function () { return String((dma_pageContext.get("lastyear1") ?? "")) + "년"; } },
        { childId: "__rb9", fn: function () { return String((dma_pageContext.get("curryear") ?? "")) + "년"; } },
        { childId: "__rb12", fn: function () { return String((dma_pageContext.get("lastyear2") ?? "")) + "년"; } },
        { childId: "__rb13", fn: function () { return String((dma_pageContext.get("lastyear1") ?? "")) + "년"; } },
        { childId: "__rb14", fn: function () { return String((dma_pageContext.get("curryear") ?? "")) + "년"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const f = (document.form || { elements: [] });
    scwin.periodChange();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rd_gubun_onclick
 * @description rd_gubun 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_gubun_onclick = function(e){
    try {
        scwin.periodChange($c.util.getComponent("rd_gubun"))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf60001.rd_gubun_onclick' }); }
};

/**
 * @method
 * @name img_49_onclick
 * @description 「화남」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_49_onclick = async function(e){
    try {
        await scwin.dsclSearch()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf60001.img_49_onclick' }); }
};

/**
 * @method
 * @name img_430_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_430_onclick = async function(e){
    try {
        await scwin.preView()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf60001.img_430_onclick' }); }
};

/**
 * @method
 * @name img_432_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_432_onclick = async function(e){
    try {
        await scwin.excel('' + dma_toDate.get("strDate") + '','' + dma_toDate.get("endDate") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf60001.img_432_onclick' }); }
};

/**
 * @method
 * @name img_434_onclick
 * @description 「[없음]」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_434_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf60001.img_434_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_preView
 * @description pre View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_preView = async function () {
    const sbmOptions = {
        id: "tx_fn_preView",
        method: "post",
        action: "/DscltrendInfo.do?method=dsclTrendPreView&gubun=null",
        ref: "dma_preViewReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_dsclSearch
 * @description dscl Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_dsclSearch = async function () {
    const sbmOptions = {
        id: "tx_fn_dsclSearch",
        method: "post",
        action: "/DscltrendInfo.do",
        ref: "dma_dsclSearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_excel
 * @description excel 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_excel = async function () {
    try { return await $c.data.downFile("/DscltrendInfo.do?method=dsclTrendExcel&str_dt=", "", ($c.util.getComponent("dma_excelReq") ? $c.util.getComponent("dma_excelReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name preView
 * @description pre View 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.preView = async function () {
    const f = (document.form || { elements: [] });
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/DscltrendInfo.do?method=dsclTrendPreView&rd_gubun=null", unresolved: "nav:" + "/DscltrendInfo.do?method=dsclTrendPreView&rd_gubun=null" }; })();

    f.action = "/DscltrendInfo.do?method=dsclTrendPreView&gubun=null";
    $c.util.getComponent('dma_preViewReq').set('SCREN_PROCES_TP_CD', "01");
    f.target = '';
    f.action = '';
};

/**
 * @method
 * @name excel
 * @description excel 처리
 * @param {*} str_dt str_dt
 * @param {*} end_dt end_dt
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excel = async function (str_dt, end_dt) {
    const f = (document.form || { elements: [] });
    f.action = "/DscltrendInfo.do?method=dsclTrendExcel&str_dt=" + str_dt + "&end_dt=" + end_dt;
    $c.util.getComponent('dma_preViewReq').set('SCREN_PROCES_TP_CD', "07");
    await scwin.tx_fn_excel();
};

/**
 * @method
 * @name dsclSearch
 * @description dscl Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dsclSearch = async function () {
    const f = (document.form || { elements: [] });
    if ($c.util.getComponent('cal_strDt') != null) {
        if (($c.util.getComponent('cal_strDt').getValue() == null ? '' : String($c.util.getComponent('cal_strDt').getValue())) === '' && $c.util.getComponent('cal_strDt') != null) {
            await $c.win.alert("시작일을 지정해주세요.");
            $c.util.getComponent("cal_strDt").focus();
            return;
        }
    }
    if (($c.util.getComponent('cal_endDt').getValue() == null ? '' : String($c.util.getComponent('cal_endDt').getValue())) === '') {
        await $c.win.alert("종료일을 지정해주세요.");
        $c.util.getComponent("cal_endDt").focus();
        return;
    }
    f.action = "/DscltrendInfo.do";
    $c.util.getComponent('dma_preViewReq').set('SCREN_PROCES_TP_CD', "01");
    $c.util.getComponent('dma_preViewReq').set('method', "dsclTrendView");
    await scwin.tx_fn_dsclSearch();
};

/**
 * @method
 * @name periodChange
 * @description period Change 처리
 * @returns {void}
 * @hidden N
 */
scwin.periodChange = function () {
    let objValue = "";
    if (($c.util.getComponent('rd_gubun').getValue() === '1')) {
        objValue = "1";
    } else {
        if (($c.util.getComponent('rd_gubun').getValue() === '2')) {
            objValue = "2";
        }
    }
    if (objValue === "1") {
        self.id_period.innerHTML = "<input name='str_dt' type='text' class='input' style='width:120px' value='null'/><a href='javascript:void(0);'><img src='/img/dscltrend/ic_cal.gif' width='20' height='18' align='absmiddle'></a> ~ <input name='end_dt' type='text' class='input' style='width:120px' value='null' /><a href='javascript:void(0);'><img src='/img/dscltrend/ic_cal.gif' width='20' height='18' align='absmiddle'></a>";
    } else {
        self.id_period.innerHTML = "<input name='end_dt' type='text' class='input' style='width:120px' value='null' /><a href='javascript:void(0);'><img src='/img/dscltrend/ic_cal.gif' width='20' height='18' align='absmiddle'></a>";
    }
};
